@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: light;
  --mm-ink: #0a0a0a;
  --mm-body: #3d3d3d;
  --mm-muted: #5f5f5f;
  --mm-line: #ebe4d8;
  --mm-soft: #f4f4f4;
  --mm-canvas: #ffffff;
  --mm-yellow: #ffc247;
  --mm-placeholder: #8a8a8a;
  --mm-focus: #ffc247;
}

html {
  background: var(--mm-canvas);
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--mm-canvas);
  color: var(--mm-ink);
  font-family: var(--font-inter), system-ui, sans-serif;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

* {
  box-sizing: border-box;
}

/* Form controls: explicit colors so OS dark mode cannot wash out text */
@layer base {
  input[type='text'],
  input[type='email'],
  input[type='tel'],
  input[type='url'],
  input[type='search'],
  input[type='password'],
  input:not([type]),
  textarea,
  select {
    color: var(--mm-ink) !important;
    background-color: var(--mm-canvas) !important;
    border: 1px solid var(--mm-line);
    caret-color: var(--mm-ink);
  }

  input::placeholder,
  textarea::placeholder {
    color: var(--mm-placeholder) !important;
    opacity: 1;
  }

  input:disabled,
  textarea:disabled,
  select:disabled,
  button:disabled {
    opacity: 0.55;
    cursor: not-allowed;
  }

  input:focus-visible,
  textarea:focus-visible,
  select:focus-visible,
  button:focus-visible,
  a:focus-visible {
    outline: 2px solid var(--mm-focus);
    outline-offset: 2px;
  }
}

@layer components {
  .mm-input {
    @apply w-full rounded-xl px-4 py-3 text-base transition-colors;
    color: var(--mm-ink);
    background-color: var(--mm-canvas);
    border: 1px solid var(--mm-line);
  }

  .mm-input:hover {
    border-color: #d9d0c2;
  }

  .mm-input:focus {
    border-color: var(--mm-yellow);
    box-shadow: 0 0 0 3px rgba(255, 194, 71, 0.35);
    outline: none;
  }

  .mm-input-error {
    border-color: #fca5a5 !important;
  }

  .mm-input-error:focus {
    box-shadow: 0 0 0 3px rgba(185, 28, 28, 0.2);
  }

  .mm-btn-primary {
    @apply inline-flex items-center justify-center gap-2 rounded-xl px-6 py-3.5 text-base font-semibold transition-colors;
    background: var(--mm-yellow);
    color: var(--mm-ink);
  }

  .mm-btn-primary:hover {
    background: #f0b020;
  }

  .mm-btn-secondary {
    @apply inline-flex items-center justify-center gap-2 rounded-xl px-6 py-3.5 text-base font-semibold transition-colors;
    background: transparent;
    color: var(--mm-ink);
    border: 1.5px solid var(--mm-ink);
  }

  .mm-btn-secondary:hover {
    background: var(--mm-soft);
  }

  .mm-panel {
    @apply rounded-2xl border bg-white;
    border-color: var(--mm-line);
    box-shadow: 0 1px 2px rgba(10, 10, 10, 0.04), 0 8px 24px rgba(10, 10, 10, 0.06);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulseSoft {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.45;
  }
}

.animate-fade-in {
  animation: fadeIn 0.35s ease-out;
}

.animate-pulse-slow {
  animation: pulseSoft 1.6s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .animate-fade-in,
  .animate-pulse-slow {
    animation: none;
  }
}

